To resolve this issue I implemented opening harpoon again in snacks picker. Pasting here in case someone needs:
```
return {
  "ThePrimeagen/harpoon",
  branch = "harpoon2",
  dependencies = { "nvim-lua/plenary.nvim" },
  keys = function()
    local status_ok, harpoon = pcall(require, "harpoon")
    if not status_ok then
      return
    end
    -- picker
    local function generate_harpoon_picker()
      local file_paths = {}
      for _, item in ipairs(harpoon:list().items) do
        table.insert(file_paths, {
          text = item.value,
          file = item.value,
        })
      end
      return file_paths
    end
    local keys = {
      {
        "<leader>H",
        function()
          require("harpoon"):list():add()
          local filename = vim.fn.expand("%:t")
          vim.api.nvim_echo({
            { "Harpooned the shit out of ", "None" },
            { filename, "Title" }, -- Title is often bold in most color schemes
          }, false, {})
        end,
        desc = "Harpoon File",
      },
      {
        "<leader>fh",
        function()
          Snacks.picker({
            finder = generate_harpoon_picker,
            win = {
              input = {
                keys = {
                  ["dd"] = { "harpoon_delete", mode = { "n", "x" } },
                },
              },
              list = {
                keys = {
                  ["dd"] = { "harpoon_delete", mode = { "n", "x" } },
                },
              },
            },
            actions = {
              harpoon_delete = function(picker, item)
                local to_remove = item or picker:selected()
                table.remove(harpoon:list().items, to_remove.idx)
                picker:find({
                  refresh = true, -- refresh picker after removing values
                })
              end,
            },
          })
        end,
      },
    }
    for i = 1, 5 do
      table.insert(keys, {
        "<leader>" .. i,
        function()
          require("harpoon"):list():select(i)
        end,
        desc = "Harpoon to File " .. i,
      })
    end
    return keys
  end,
}

